(5149122, 749494, 101117, '<td valign="top">Nice enough pic, colours are a bit psychedelic though, which is distracting.</td>', 'Nice enough pic, colours are a bit psychedelic though, which is distracting.', '2008-12-24 06:52:58.000000', NULL, 1),
(5149125, 748924, 101117, '<td valign="top">Nice depth on the sky. The colours are a little uninteresting, possibly because there are a lot of pale tones without any real contrast. Adjusting this with curves to give it more contrast could really help.<br/> <br/>Wouldn''t change much compositionally, it has nice foreground, mid and background elements.</td>', 'Nice depth on the sky. The colours are a little uninteresting, possibly because there are a lot of pale tones without any real contrast. Adjusting this with curves to give it more contrast could really help. Wouldn''t change much compositionally, it has nice foreground, mid and background elements.', '2008-12-24 06:57:46.000000', NULL, 1),
(5149128, 749242, 101117, '<td valign="top">This could be good, unfortunately neither the figure or the shadow are in focus which really lets it down.</td>', 'This could be good, unfortunately neither the figure or the shadow are in focus which really lets it down.', '2008-12-24 06:59:39.000000', NULL, 1),
(5149129, 749469, 101117, '<td valign="top">Think this would have worked better had you upped the contrast. As it is all the colours are quite samey and the shadow isn''t as striking as it could be.</td>', 'Think this would have worked better had you upped the contrast. As it is all the colours are quite samey and the shadow isn''t as striking as it could be.', '2008-12-24 07:00:35.000000', NULL, 1),
