(5149556, 749270, 101318, '<td valign="top">Those are some impressively large tacks</td>', 'Those are some impressively large tacks', '2008-12-24 12:02:09.000000', NULL, 1),
(5149559, 749509, 96751, '<td valign="top">I love double-vaulted church ceilings.  Nice image.  A bit over sharpened and contrasty for me.  The right lighting is overblown and draws the ey there, rather than to the shadows above.</td>', 'I love double-vaulted church ceilings.  Nice image.  A bit over sharpened and contrasty for me.  The right lighting is overblown and draws the ey there, rather than to the shadows above.', '2008-12-24 12:02:57.000000', NULL, 1),
