(5149566, 749396, 96751, '<td valign="top">Great, powerful shot.  Crisp, well-balanced, totally fits the challenge.</td>', 'Great, powerful shot.  Crisp, well-balanced, totally fits the challenge.', '2008-12-24 12:04:49.000000', NULL, 1),
