(5149578, 749416, 96751, '<td valign="top">Stunning.  I expect to see this on the front page.  Beautiful detail and color on the leaf, crisp and interesting shadow shape, intriguing bokeh on object.  The diagonal lign of the leaf edge really adds to this shot.</td>', 'Stunning.  I expect to see this on the front page.  Beautiful detail and color on the leaf, crisp and interesting shadow shape, intriguing bokeh on object.  The diagonal lign of the leaf edge really adds to this shot.', '2008-12-24 12:08:17.000000', NULL, 1),
(5149582, 748691, 96751, '<td valign="top">This is going to be a postcard.  Very beautiful and powerful shot.  But I think the bridge is much more of a feature for this challenge than the shadow, which although quite large, is less noticeable than the structure and the white roiling water and snow.</td>', 'This is going to be a postcard.  Very beautiful and powerful shot.  But I think the bridge is much more of a feature for this challenge than the shadow, which although quite large, is less noticeable than the structure and the white roiling water and snow.', '2008-12-24 12:09:40.000000', NULL, 1),
(5149583, 749335, 96751, '<td valign="top">Great bee macro.  Shadow, not so much</td>', 'Great bee macro.  Shadow, not so much', '2008-12-24 12:10:10.000000', NULL, 1),
