(5151272, 748681, 31772, '<td valign="top">I think this picture doesn''t have a shadow, but rather a reflection. Two different things.</td>', 'I think this picture doesn''t have a shadow, but rather a reflection. Two different things.', '2008-12-25 21:53:06.000000', NULL, 1),
(5151273, 748971, 31772, '<td valign="top">It''s an interesting picture, but I don''t see any shadows.</td>', 'It''s an interesting picture, but I don''t see any shadows.', '2008-12-25 21:53:45.000000', NULL, 1),
(5151274, 749543, 31772, '<td valign="top">Very nice picture, well done!</td>', 'Very nice picture, well done!', '2008-12-25 21:54:01.000000', NULL, 1),
(5151276, 748658, 31772, '<td valign="top">Cool picture, rather dark, I''m not sure what''s happening here.</td>', 'Cool picture, rather dark, I''m not sure what''s happening here.', '2008-12-25 21:54:25.000000', NULL, 1),
(5151277, 749550, 31772, '<td valign="top">Great expression on your face, and interesting use of shadows. Well done!</td>', 'Great expression on your face, and interesting use of shadows. Well done!', '2008-12-25 21:54:55.000000', NULL, 1),
(5151278, 749585, 31772, '<td valign="top">Very nice macro shot, great detail on the pencil and dictionary. Neat use of shadow.</td>', 'Very nice macro shot, great detail on the pencil and dictionary. Neat use of shadow.', '2008-12-25 21:56:07.000000', NULL, 1),
(5151370, 749379, 76335, '<td valign="top">Good idea, but sharper focus would have helped.</td>', 'Good idea, but sharper focus would have helped.', '2008-12-25 23:23:15.000000', NULL, 1),
(5151383, 749230, 76335, '<td valign="top">Fairly well done. The shadow is strong, and we don''t see you holding a camera to your face, which is good.</td>', 'Fairly well done. The shadow is strong, and we don''t see you holding a camera to your face, which is good.', '2008-12-25 23:57:06.000000', NULL, 1),
(5151395, 749590, 31772, '<td valign="top">A very interesting picture, love the repeating pattern. Top marks!</td>', 'A very interesting picture, love the repeating pattern. Top marks!', '2008-12-26 00:24:42.000000', NULL, 1),
(5151444, 749407, 97225, '<td valign="top">Beautiful irridescence in the green. It is a lovely shot.</td>', 'Beautiful irridescence in the green. It is a lovely shot.', '2008-12-26 01:13:46.000000', NULL, 1),
(5151445, 749467, 97225, '<td valign="top">Nice sense of menace.</td>', 'Nice sense of menace.', '2008-12-26 01:14:24.000000', NULL, 1),
(5151448, 749469, 97225, '<td valign="top">Well caught.</td>', 'Well caught.', '2008-12-26 01:15:44.000000', NULL, 1),
(5151451, 748868, 97225, '<td valign="top">This is a goodie. 9</td>', 'This is a goodie. 9', '2008-12-26 01:17:36.000000', NULL, 1),
(5151452, 749338, 97225, '<td valign="top">Nice rhythm.</td>', 'Nice rhythm.', '2008-12-26 01:18:01.000000', NULL, 1),
(5151454, 749281, 101117, '<td valign="top">Nice idea, looks a little flat though, perhaps a curves or levels adjustment could have helped bring out a touch more range.</td>', 'Nice idea, looks a little flat though, perhaps a curves or levels adjustment could have helped bring out a touch more range.', '2008-12-26 01:22:04.000000', NULL, 1),
(5151455, 748900, 101117, '<td valign="top">I like this, clever idea.</td>', 'I like this, clever idea.', '2008-12-26 01:22:48.000000', NULL, 1),
(5151456, 748535, 97225, '<td valign="top">Nice shadows, beaut sculpture.</td>', 'Nice shadows, beaut sculpture.', '2008-12-26 01:25:56.000000', NULL, 1),
(5151457, 749114, 101117, '<td valign="top">Nice shot, well put together. Would have been nice if you could bring a little more detail out in the left eye while keeping the shadow. Also, the background texture is a touch distracting, particularly on the left side where the light is coming from. Perhaps a few steps away (from the wall?) would have corrected this. 6</td>', 'Nice shot, well put together. Would have been nice if you could bring a little more detail out in the left eye while keeping the shadow. Also, the background texture is a touch distracting, particularly on the left side where the light is coming from. Perhaps a few steps away (from the wall?) would have corrected this. 6', '2008-12-26 01:26:16.000000', NULL, 1),
(5151458, 749399, 101117, '<td valign="top">Like the shadows here, particularly the curved ones inside the pots, good positioning of the light source.</td>', 'Like the shadows here, particularly the curved ones inside the pots, good positioning of the light source.', '2008-12-26 01:26:55.000000', NULL, 1),
(5151459, 748626, 97225, '<td valign="top">Nice image. I like the way you have set them up.</td>', 'Nice image. I like the way you have set them up.', '2008-12-26 01:27:05.000000', NULL, 1),
(5151462, 748962, 97225, '<td valign="top">Interesting shot. It almost looks like sugar. The shadows are nice.</td>', 'Interesting shot. It almost looks like sugar. The shadows are nice.', '2008-12-26 01:28:48.000000', NULL, 1),
(5151463, 748971, 97225, '<td valign="top">Although there is light and shade here, there is no emphasis on shadows.</td>', 'Although there is light and shade here, there is no emphasis on shadows.', '2008-12-26 01:29:53.000000', NULL, 1),
(5151464, 749610, 101117, '<td valign="top">Nice shot with great colours, not too much in the way of shadows though.</td>', 'Nice shot with great colours, not too much in the way of shadows though.', '2008-12-26 01:30:13.000000', NULL, 1),
(5151465, 749550, 97225, '<td valign="top">Good shadows. The light on the eyes makes this.</td>', 'Good shadows. The light on the eyes makes this.', '2008-12-26 01:30:58.000000', NULL, 1),
(5151467, 748942, 101117, '<td valign="top">Nice shot with good colours, but I find what I assume is the window frame on the top and bottom right to be distracting.</td>', 'Nice shot with good colours, but I find what I assume is the window frame on the top and bottom right to be distracting.', '2008-12-26 01:31:49.000000', NULL, 1),
(5151468, 749486, 97225, '<td valign="top">Brilliant, sharp shadows. I like the way they point to their counterparts across the path.</td>', 'Brilliant, sharp shadows. I like the way they point to their counterparts across the path.', '2008-12-26 01:32:34.000000', NULL, 1),
(5151470, 749379, 101117, '<td valign="top">Great shot, one of the most relevant to the theme and also the season, well done.</td>', 'Great shot, one of the most relevant to the theme and also the season, well done.', '2008-12-26 01:32:39.000000', NULL, 1),
(5151471, 749282, 97225, '<td valign="top">Good idea.</td>', 'Good idea.', '2008-12-26 01:34:03.000000', NULL, 1),
(5151473, 749346, 101117, '<td valign="top">Nice title for the shot. I would like to see this if possible with deeper shadow though for more emphasis.</td>', 'Nice title for the shot. I would like to see this if possible with deeper shadow though for more emphasis.', '2008-12-26 01:34:14.000000', NULL, 1),
(5151474, 749610, 97225, '<td valign="top">That is a lovely shot. I love the blueness of the shadows.</td>', 'That is a lovely shot. I love the blueness of the shadows.', '2008-12-26 01:34:56.000000', NULL, 1),
(5151476, 748691, 101117, '<td valign="top">I like the contrast of light and dark areas on the water here, but the water itself isn''t particularly attractive. Might have been nice with a touch longer exposure to give it a softer feel. Mind you, can''t blame you if you didn''t want to hang around too long setting up a tripod, looks cold!</td>', 'I like the contrast of light and dark areas on the water here, but the water itself isn''t particularly attractive. Might have been nice with a touch longer exposure to give it a softer feel. Mind you, can''t blame you if you didn''t want to hang around too long setting up a tripod, looks cold!', '2008-12-26 01:36:39.000000', NULL, 1),
(5151478, 749398, 97225, '<td valign="top">I like this. Nice pattern of light and shadow, and the emphasis really is on the idea of cast shadows. 9</td>', 'I like this. Nice pattern of light and shadow, and the emphasis really is on the idea of cast shadows. 9', '2008-12-26 01:37:12.000000', NULL, 1),
(5151481, 748856, 97225, '<td valign="top">That is a nice composition, and the shadows play a major part. Well done.</td>', 'That is a nice composition, and the shadows play a major part. Well done.', '2008-12-26 01:38:51.000000', NULL, 1),
(5151482, 749509, 101117, '<td valign="top">Don''t really see shadows so much as unlit areas here (I''m sure there''s a difference). Also, the image seems to be skewed a touch to the left and there''s an annoying bright artefact at the bottom you should have cropped out.</td>', 'Don''t really see shadows so much as unlit areas here (I''m sure there''s a difference). Also, the image seems to be skewed a touch to the left and there''s an annoying bright artefact at the bottom you should have cropped out.', '2008-12-26 01:39:00.000000', NULL, 1),
(5151486, 749550, 101117, '<td valign="top">Nice shot, though perhaps a touch dull. I know that''s the intended mood but there''s a just too little detail here. I turned the brightness right up to see if it was just my display but still the same. Taking into account the great composition, 6 from me.</td>', 'Nice shot, though perhaps a touch dull. I know that''s the intended mood but there''s a just too little detail here. I turned the brightness right up to see if it was just my display but still the same. Taking into account the great composition, 6 from me.', '2008-12-26 01:42:18.000000', NULL, 1),
(5151488, 748275, 97225, '<td valign="top">There is light and shade here, as in almost any picture, but imo the concept of cast shadows from something is missing.</td>', 'There is light and shade here, as in almost any picture, but imo the concept of cast shadows from something is missing.', '2008-12-26 01:43:04.000000', NULL, 1),
