(5153601, 748830, 62249, '<td valign="top">Lovely. The lighting on the wheel/shadow area is very nice, and the blue/red coloration is quite pleasing.</td>', 'Lovely. The lighting on the wheel/shadow area is very nice, and the blue/red coloration is quite pleasing.', '2008-12-27 14:57:21.000000', NULL, 1),
(5153603, 749282, 62249, '<td valign="top">This is interesting. My first thought was "Hmm. Lifesaver-Henge." But then I looked at the shadows and liked how they form binary numbers. I enjoyed pondering this one for a while.</td>', 'This is interesting. My first thought was "Hmm. Lifesaver-Henge." But then I looked at the shadows and liked how they form binary numbers. I enjoyed pondering this one for a while.', '2008-12-27 14:59:31.000000', NULL, 1),
