(5154971, 749398, 100831, '<td valign="top">fun photo - great idea and very nicely done, I love the bw - my only nit-pick would be her gaze - why are her eyes looking up rather than straight forward so we could see her better?</td>', 'fun photo - great idea and very nicely done, I love the bw - my only nit-pick would be her gaze - why are her eyes looking up rather than straight forward so we could see her better?', '2008-12-28 14:25:58.000000', NULL, 1),
(5154977, 748481, 100831, '<td valign="top">simple and nice - lovely color.</td>', 'simple and nice - lovely color.', '2008-12-28 14:27:17.000000', NULL, 1),
(5155041, 749316, 88204, '<td valign="top">I love the pattern on the wall from the vase. Ideally I think I''d like the rose slightly brighter but then you''d blow out your whites more, which I understand may not work in basic editing. Cool concept.</td>', 'I love the pattern on the wall from the vase. Ideally I think I''d like the rose slightly brighter but then you''d blow out your whites more, which I understand may not work in basic editing. Cool concept.', '2008-12-28 15:07:59.000000', NULL, 1),
(5155049, 748901, 88204, '<td valign="top">Well done but these heart/ring shots are a bit too common for my tastes. I like the diagonal composition.</td>', 'Well done but these heart/ring shots are a bit too common for my tastes. I like the diagonal composition.', '2008-12-28 15:10:07.000000', NULL, 1),
(5155050, 748610, 88204, '<td valign="top">That''s very cool! Where the heck did you find a camel? We don''t have camels in my part of the world!  :)<br/> <br/>Well done!</td>', 'That''s very cool! Where the heck did you find a camel? We don''t have camels in my part of the world!  :) Well done!', '2008-12-28 15:10:50.000000', NULL, 1),
(5155054, 748523, 88204, '<td valign="top">Great mood. I like how there''s some blur and some sharp. I can''t figure out how you did it.</td>', 'Great mood. I like how there''s some blur and some sharp. I can''t figure out how you did it.', '2008-12-28 15:12:04.000000', NULL, 1),
