INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5155275, 748618, 55956, '<td valign="top">securely the best in the category:"games with the shadow", the winning thing of this photo is the simplicity. very well done.</td>', 'securely the best in the category:"games with the shadow", the winning thing of this photo is the simplicity. very well done.', '2008-12-28 18:02:18.000000', NULL, 1),
(5155284, 748869, 55956, '<td valign="top">this remember me an amazing photo of yakatme, a good shot!</td>', 'this remember me an amazing photo of yakatme, a good shot!', '2008-12-28 18:05:03.000000', NULL, 1),
(5155315, 749590, 98339, '<td valign="top">That''s kind a cool....I like this...</td>', 'That''s kind a cool....I like this...', '2008-12-28 18:48:21.000000', NULL, 1),
(5155319, 748962, 25890, '<td valign="top">Successful abstraction with only a vague sense of size, dimensions and proportions. An image not merely "of" but "about" shadows (and light, naturally). While the tonal distribution might be tweaked some so as to give the brightest highlights and the deepest shadows just a little bit more definition, the image still provides one with a delightful study of textures, shapes and forms. The concert-piano-shaped shadow gives a gentle nudge to my memory, and some pleasant but long-forgotten memories of mine begin to resurface. I like it when an image does that!</td>', 'Successful abstraction with only a vague sense of size, dimensions and proportions. An image not merely "of" but "about" shadows (and light, naturally). While the tonal distribution might be tweaked some so as to give the brightest highlights and the deepest shadows just a little bit more definition, the image still provides one with a delightful study of textures, shapes and forms. The concert-piano-shaped shadow gives a gentle nudge to my memory, and some pleasant but long-forgotten memories of mine begin to resurface. I like it when an image does that!', '2008-12-28 18:51:29.000000', NULL, 1),
(5155631, 749620, 50695, '<td valign="top">as they say in Go, you have good shape.</td>', 'as they say in Go, you have good shape.', '2008-12-28 22:36:58.000000', NULL, 1),
(5155664, 749516, 22459, '<td valign="top">I''m sorry but I don''t think that this meets the challenge description. It is also a poorly captured image so therefore I need to score it low...very low</td>', 'I''m sorry but I don''t think that this meets the challenge description. It is also a poorly captured image so therefore I need to score it low...very low', '2008-12-28 23:05:36.000000', NULL, 1),
(5155684, 748691, 73452, '<td valign="top">really nicely composed, and the black and white compliment the long shadows very well.</td>', 'really nicely composed, and the black and white compliment the long shadows very well.', '2008-12-28 23:26:21.000000', NULL, 1),
(5155686, 749242, 73452, '<td valign="top">well, im not really sure how to take this image.  its not focused, its not really composed well, and though there is a shadow, im not sure it adds to the photo at all.  good luck though!</td>', 'well, im not really sure how to take this image.  its not focused, its not really composed well, and though there is a shadow, im not sure it adds to the photo at all.  good luck though!', '2008-12-28 23:27:10.000000', NULL, 1),
(5155687, 749630, 73452, '<td valign="top">wow, this is polar opposite of what we hav ehere!</td>', 'wow, this is polar opposite of what we hav ehere!', '2008-12-28 23:27:26.000000', NULL, 1),
(5155689, 748900, 100107, '<td valign="top">lol...classic</td>', 'lol...classic', '2008-12-28 23:27:50.000000', NULL, 1),
(5155692, 749486, 61666, '<td valign="top">Does give a ''grim'' look, but maybe not as haunting as desired.<br/> <br/>Perhaps if the camera was close to the ground, and a wider lens was used,<br/>it would make the shadow in the foreground more threatening. <br/> <br/>The shadows should be the first thing to catch the eye, but the brightness &amp; positioning of the facing surfaces make you see the shadow later.</td>', 'Does give a ''grim'' look, but maybe not as haunting as desired. Perhaps if the camera was close to the ground, and a wider lens was used,it would make the shadow in the foreground more threatening.  The shadows should be the first thing to catch the eye, but the brightness & positioning of the facing surfaces make you see the shadow later.', '2008-12-28 23:30:04.000000', NULL, 1),
(5155694, 749260, 61666, '<td valign="top">Nice positioning of the letters - can read just enough.<br/> <br/>It''d be nice if the face were turned a little more, so that some shadows on the face would stand out. Might be hard due to the spring attachmnt, but should be possible :)</td>', 'Nice positioning of the letters - can read just enough. It''d be nice if the face were turned a little more, so that some shadows on the face would stand out. Might be hard due to the spring attachmnt, but should be possible :)', '2008-12-28 23:31:18.000000', NULL, 1),
(5155696, 749648, 73452, '<td valign="top">beautiful, i love snow on fallen trees such as this.</td>', 'beautiful, i love snow on fallen trees such as this.', '2008-12-28 23:34:02.000000', NULL, 1),
(5155697, 749413, 61666, '<td valign="top">Nice choice of background to match the color of the dummy - or was the flash filtered to be orange?<br/> <br/>I notice some low-iso noise, but that could be my monitor :)<br/> <br/>The shadows need much more contrast - something hard to do, as a brighter light source for one shadow would probably make the other shadows lighter.<br/> <br/>However, a directional spotlight with some tinkering should help...<br/> <br/>Great concept, maybe better execution? :)</td>', 'Nice choice of background to match the color of the dummy - or was the flash filtered to be orange? I notice some low-iso noise, but that could be my monitor :) The shadows need much more contrast - something hard to do, as a brighter light source for one shadow would probably make the other shadows lighter. However, a directional spotlight with some tinkering should help... Great concept, maybe better execution? :)', '2008-12-28 23:34:45.000000', NULL, 1),
(5155698, 748856, 73452, '<td valign="top">simple and elegant, maybe a darker shadow would have really pulled me in more, perosnal taste thing though.  nicely done.</td>', 'simple and elegant, maybe a darker shadow would have really pulled me in more, perosnal taste thing though.  nicely done.', '2008-12-28 23:35:43.000000', NULL, 1),
(5155699, 748348, 100107, '<td valign="top">lol</td>', 'lol', '2008-12-28 23:35:44.000000', NULL, 1),
(5155701, 748618, 73452, '<td valign="top">i''ve been staring at a nail turned dancer on the front page to see a nail turned into a devil, oh the humanity of it all!</td>', 'i''ve been staring at a nail turned dancer on the front page to see a nail turned into a devil, oh the humanity of it all!', '2008-12-28 23:36:18.000000', NULL, 1),
(5155702, 748396, 61666, '<td valign="top">The shadow needs some more contrast to draw the eyes towards it at first, not as an afterthought.<br/>Could this be sharpened in photoshop? <br/> <br/>Some cropping to put the shadow closer to the middle might also help.<br/> <br/>Good concept!</td>', 'The shadow needs some more contrast to draw the eyes towards it at first, not as an afterthought.Could this be sharpened in photoshop?  Some cropping to put the shadow closer to the middle might also help. Good concept!', '2008-12-28 23:36:32.000000', NULL, 1),
(5155703, 749550, 73452, '<td valign="top">very interesting lihgting choice, i really like it.  and the way the light hits the drink in the cup as well just is beautiful</td>', 'very interesting lihgting choice, i really like it.  and the way the light hits the drink in the cup as well just is beautiful', '2008-12-28 23:36:46.000000', NULL, 1),
(5155705, 749242, 100107, '<td valign="top">Too blurry for my liking</td>', 'Too blurry for my liking', '2008-12-28 23:37:21.000000', NULL, 1),
(5155708, 749338, 61666, '<td valign="top">Some more levels of depth/variation would help.<br/> <br/>Even for the singular pattern of shadows, the uniformity doesnt show through... there are breaks in the shadows from the 4rd column on, that take away from the singularity of the theme.</td>', 'Some more levels of depth/variation would help. Even for the singular pattern of shadows, the uniformity doesnt show through... there are breaks in the shadows from the 4rd column on, that take away from the singularity of the theme.', '2008-12-28 23:38:24.000000', NULL, 1),
(5155710, 749407, 61666, '<td valign="top">where are the shadows?</td>', 'where are the shadows?', '2008-12-28 23:38:48.000000', NULL, 1),
(5155712, 749407, 22459, '<td valign="top">actually the green colour is an optical illusion.</td>', 'actually the green colour is an optical illusion.', '2008-12-28 23:39:42.000000', NULL, 1),
(5155717, 749260, 100107, '<td valign="top">shame you didn''t have the whole shadow in the photo</td>', 'shame you didn''t have the whole shadow in the photo', '2008-12-28 23:41:58.000000', NULL, 1),
(5155718, 749486, 73452, '<td valign="top">spooky</td>', 'spooky', '2008-12-28 23:42:19.000000', NULL, 1),
(5155720, 749396, 61666, '<td valign="top">Wow! I love it :)<br/> <br/>Rather than the ''light'' being the theme of the image, its the shadows!<br/>Just what''s called for in this challenge!<br/> <br/>The backs of the trees being so dark, and the grass having strong shadows help.<br/> <br/>Good job keeping the focus on the shadow - it almost looks like a trench.<br/> <br/><strike>One nitpick - It would better if the shadow started from the coner of the image...</strike> <br/>**scratch that**** diagnoal from the corner usually works as the ''theme'' is what the diagnoal leads the eyes to.<br/>In this case, the theme *is* the diagonal shadow (or its part of the theme), instead of the tree it leads to.<br/> <br/>So its better the way you left it.<br/> <br/>Nice :)</td>', 'Wow! I love it :) Rather than the ''light'' being the theme of the image, its the shadows!Just what''s called for in this challenge! The backs of the trees being so dark, and the grass having strong shadows help. Good job keeping the focus on the shadow - it almost looks like a trench. One nitpick - It would better if the shadow started from the coner of the image... **scratch that**** diagnoal from the corner usually works as the ''theme'' is what the diagnoal leads the eyes to.In this case, the theme *is* the diagonal shadow (or its part of the theme), instead of the tree it leads to. So its better the way you left it. Nice :)', '2008-12-28 23:43:35.000000', NULL, 1),
(5155722, 749036, 61666, '<td valign="top">Hard to notice the shadow.</td>', 'Hard to notice the shadow.', '2008-12-28 23:43:57.000000', NULL, 1),
(5155723, 749469, 100107, '<td valign="top">not quite.</td>', 'not quite.', '2008-12-28 23:44:07.000000', NULL, 1),
(5155726, 748412, 61666, '<td valign="top">Like the rustic, down-to-earth look.<br/> <br/>Makes you feel like you want to go back in time, and pick up the ball.<br/> <br/>Focus is great. Would be nice if the foreground rocks/etc coud be more out of focus, but that might''ve been really hard. Would be interesting to see the exif data.</td>', 'Like the rustic, down-to-earth look. Makes you feel like you want to go back in time, and pick up the ball. Focus is great. Would be nice if the foreground rocks/etc coud be more out of focus, but that might''ve been really hard. Would be interesting to see the exif data.', '2008-12-28 23:45:34.000000', NULL, 1),
(5155731, 748412, 100107, '<td valign="top">bit to dark</td>', 'bit to dark', '2008-12-28 23:47:02.000000', NULL, 1),
(5155740, 749480, 61666, '<td valign="top">Wow, nice impact.<br/> <br/>OVerall, very well forumlated. Everything fits together perfectly to deliver the desired singular message!</td>', 'Wow, nice impact. OVerall, very well forumlated. Everything fits together perfectly to deliver the desired singular message!', '2008-12-28 23:50:41.000000', NULL, 1),
(5155741, 749460, 61666, '<td valign="top">Like how the outline of the shadow matches the look of the rocks.<br/> <br/>Perhaps the leaves to the right weren''t needed. Without them it looks like a nice painting :)</td>', 'Like how the outline of the shadow matches the look of the rocks. Perhaps the leaves to the right weren''t needed. Without them it looks like a nice painting :)', '2008-12-28 23:51:37.000000', NULL, 1),
(5155742, 749270, 61666, '<td valign="top">Nice concept. The black &amp; white ones cause confusion though, as one makes you think its a shadow, and the somewhat blends into the background.</td>', 'Nice concept. The black & white ones cause confusion though, as one makes you think its a shadow, and the somewhat blends into the background.', '2008-12-28 23:52:57.000000', NULL, 1),
(5155745, 748962, 61666, '<td valign="top">Whoa! nice. amazing. Speechless :)</td>', 'Whoa! nice. amazing. Speechless :)', '2008-12-28 23:53:55.000000', NULL, 1),
(5155749, 749079, 61666, '<td valign="top">The photo matches very well with its title theme.<br/> <br/>Even though the lady''s hair/dress aren''t "shadows", they look like them :)<br/> <br/>Love the sharp outline of her hand - how''d u get that?<br/> <br/>The columns on the right does portay the sense that this is possibly outside a courthouse...</td>', 'The photo matches very well with its title theme. Even though the lady''s hair/dress aren''t "shadows", they look like them :) Love the sharp outline of her hand - how''d u get that? The columns on the right does portay the sense that this is possibly outside a courthouse...', '2008-12-28 23:55:33.000000', NULL, 1),
(5155751, 749000, 61666, '<td valign="top">Some more contrast would help in the shadow...</td>', 'Some more contrast would help in the shadow...', '2008-12-28 23:56:21.000000', NULL, 1),
(5155752, 748610, 61666, '<td valign="top">The sand patterns could really benefit from some shadow too... all that was needed was to find patterns tangent to the sun!</td>', 'The sand patterns could really benefit from some shadow too... all that was needed was to find patterns tangent to the sun!', '2008-12-28 23:57:22.000000', NULL, 1),
(5155755, 749525, 61666, '<td valign="top">Love the way the dog is facing, and how the ''dunes'' are spread out to portray a sense of ''territory out there to explore''.<br/> <br/>Amazing how the tiny specs of snow have shadows, as well as some of the fur.</td>', 'Love the way the dog is facing, and how the ''dunes'' are spread out to portray a sense of ''territory out there to explore''. Amazing how the tiny specs of snow have shadows, as well as some of the fur.', '2008-12-28 23:58:47.000000', NULL, 1),
(5155757, 749467, 61666, '<td valign="top">Like the perspective :) Definitely put the shadows as the theme.<br/> <br/>Coldn''t fully understand the ''watch it'' part though. Where''s the weapon?</td>', 'Like the perspective :) Definitely put the shadows as the theme. Coldn''t fully understand the ''watch it'' part though. Where''s the weapon?', '2008-12-28 23:59:51.000000', NULL, 1),
(5155801, 749626, 102031, '<td valign="top">That''s a really interesting effect.  Now I want to get my camera out and take pictures of candles.  :-D.  I especially like the reddish coloring.</td>', 'That''s a really interesting effect.  Now I want to get my camera out and take pictures of candles.  :-D.  I especially like the reddish coloring.', '2008-12-29 00:14:42.000000', NULL, 1),
(5155807, 749488, 102031, '<td valign="top">It''s a really good idea, but I know I''ve seen it (one like it at least) before.  Nevertheless, I like it anyways.</td>', 'It''s a really good idea, but I know I''ve seen it (one like it at least) before.  Nevertheless, I like it anyways.', '2008-12-29 00:16:15.000000', NULL, 1),
(5155808, 749464, 102031, '<td valign="top">Very confusing trying to figure out exactly what is where in this picture.<br/> <br/>I like the end effect though.  The yellowish tint also makes it feel more natural in this case.</td>', 'Very confusing trying to figure out exactly what is where in this picture. I like the end effect though.  The yellowish tint also makes it feel more natural in this case.', '2008-12-29 00:16:56.000000', NULL, 1),
(5155816, 749036, 102031, '<td valign="top">The shadows in this picture are not as direct as most of the others I''ve seen in this contest, but the effect is still very cool (no pun intended).</td>', 'The shadows in this picture are not as direct as most of the others I''ve seen in this contest, but the effect is still very cool (no pun intended).', '2008-12-29 00:20:28.000000', NULL, 1),
