(5155836, 749379, 102031, '<td valign="top">Very appropriate for the season.  A little sharper would have been nice, but I like it anyways.</td>', 'Very appropriate for the season.  A little sharper would have been nice, but I like it anyways.', '2008-12-29 00:32:01.000000', NULL, 1),
