(5157651, 749610, 88492, '<td valign="top">love the colour in the snow (7)</td>', 'love the colour in the snow (7)', '2008-12-30 08:22:57.000000', NULL, 1),
(5157652, 748792, 88492, '<td valign="top">Arranged differently, I''m sure you could have made a more interesting shadow.</td>', 'Arranged differently, I''m sure you could have made a more interesting shadow.', '2008-12-30 08:24:37.000000', NULL, 1),
(5157727, 749203, 102024, '<td valign="top">I think we''ve all been there... haha, captures the emotion quite well.</td>', 'I think we''ve all been there... haha, captures the emotion quite well.', '2008-12-30 09:55:29.000000', NULL, 1),
(5157798, 748658, 30982, '<td valign="top">I do quite like this, especially that sea of light he''s walking into and the beacon above.  It''s a bit small - make sure that you have the long side at 640 pixels for basic challenges so we can see it well.  Very nice shot.</td>', 'I do quite like this, especially that sea of light he''s walking into and the beacon above.  It''s a bit small - make sure that you have the long side at 640 pixels for basic challenges so we can see it well.  Very nice shot.', '2008-12-30 11:03:07.000000', NULL, 1),
(5157800, 749396, 30982, '<td valign="top">Yep, this definitely works for me.  Great perspective, very good use of wide, and a "draw you in" kinda thing going on with the shadow.  Nice.</td>', 'Yep, this definitely works for me.  Great perspective, very good use of wide, and a "draw you in" kinda thing going on with the shadow.  Nice.', '2008-12-30 11:03:51.000000', NULL, 1),
(5157801, 749230, 3540, '<td valign="top">Love the idea.  The tinted glass makes for a nice effect.  The darkness on the left takes something away though.</td>', 'Love the idea.  The tinted glass makes for a nice effect.  The darkness on the left takes something away though.', '2008-12-30 11:03:56.000000', NULL, 1),
(5157803, 749486, 30982, '<td valign="top">Very much like the composition of the shadowed masoleums and the very stark sunlit ones.  Very cool feel to this.</td>', 'Very much like the composition of the shadowed masoleums and the very stark sunlit ones.  Very cool feel to this.', '2008-12-30 11:04:22.000000', NULL, 1),
(5157806, 749378, 30982, '<td valign="top">Cold and lovely, though I suspect the cold is IR''d?  Still darn cold and nice job shooting into the sun.</td>', 'Cold and lovely, though I suspect the cold is IR''d?  Still darn cold and nice job shooting into the sun.', '2008-12-30 11:05:04.000000', NULL, 1),
(5157808, 748830, 30982, '<td valign="top">Quite lovely!  Nice softness and good balance between the shadow and the object itself.</td>', 'Quite lovely!  Nice softness and good balance between the shadow and the object itself.', '2008-12-30 11:05:44.000000', NULL, 1),
(5157809, 749230, 30982, '<td valign="top">I like this.</td>', 'I like this.', '2008-12-30 11:05:52.000000', NULL, 1),
(5157815, 749316, 3540, '<td valign="top">Good idea.  I think a little negative space would do this one some good.  Its just too tight of a crop for my tastes.</td>', 'Good idea.  I think a little negative space would do this one some good.  Its just too tight of a crop for my tastes.', '2008-12-30 11:09:41.000000', NULL, 1),
(5157823, 749198, 3540, '<td valign="top">Nice work.  Best image I''ve seen so far.</td>', 'Nice work.  Best image I''ve seen so far.', '2008-12-30 11:12:09.000000', NULL, 1),
(5157826, 749282, 3540, '<td valign="top">Looking at this, I think you should have titled it "Binary".  I think there could be a successful image made with this type of setup.  This is not it however...</td>', 'Looking at this, I think you should have titled it "Binary".  I think there could be a successful image made with this type of setup.  This is not it however...', '2008-12-30 11:14:25.000000', NULL, 1),
(5157828, 748924, 3540, '<td valign="top">Not seeing any relevance to the challenge... sorry</td>', 'Not seeing any relevance to the challenge... sorry', '2008-12-30 11:15:41.000000', NULL, 1),
(5157831, 749648, 3540, '<td valign="top">This is awesome composition.  As is, its pretty good.  Its too sharp for me. 8</td>', 'This is awesome composition.  As is, its pretty good.  Its too sharp for me. 8', '2008-12-30 11:18:44.000000', NULL, 1),
(5157832, 749590, 3540, '<td valign="top">9.  Geometric Composition is def one of my fav''s</td>', '9.  Geometric Composition is def one of my fav''s', '2008-12-30 11:19:31.000000', NULL, 1),
(5157833, 749242, 3540, '<td valign="top">Tat2</td>', 'Tat2', '2008-12-30 11:19:59.000000', NULL, 1),
(5157835, 749467, 3540, '<td valign="top">Strange perspective.  Nice crocs</td>', 'Strange perspective.  Nice crocs', '2008-12-30 11:21:09.000000', NULL, 1),
(5157849, 749116, 3540, '<td valign="top">Looks oversharpened.</td>', 'Looks oversharpened.', '2008-12-30 11:27:12.000000', NULL, 1),
(5157852, 748900, 3540, '<td valign="top">I see you had good intentions with this one.  Not well executed. 5</td>', 'I see you had good intentions with this one.  Not well executed. 5', '2008-12-30 11:29:10.000000', NULL, 1),
(5157858, 749494, 3540, '<td valign="top">I see this more about color than shadow.  Maybe a little change in the lighting and you have an effective product endorsement</td>', 'I see this more about color than shadow.  Maybe a little change in the lighting and you have an effective product endorsement', '2008-12-30 11:30:32.000000', NULL, 1),
(5157866, 748412, 3540, '<td valign="top">Too tight on the subject for my tastes.  overall not a bad image though. 6</td>', 'Too tight on the subject for my tastes.  overall not a bad image though. 6', '2008-12-30 11:33:50.000000', NULL, 1),
(5157870, 749550, 3540, '<td valign="top">Like the subject, I''d have framed it differently though. 7</td>', 'Like the subject, I''d have framed it differently though. 7', '2008-12-30 11:36:12.000000', NULL, 1),
(5157875, 748795, 3540, '<td valign="top">Coffee lover too... photo is pretty good too</td>', 'Coffee lover too... photo is pretty good too', '2008-12-30 11:39:02.000000', NULL, 1),
(5157942, 748856, 3087, '<td valign="top">Simple, nicely executed, classic.</td>', 'Simple, nicely executed, classic.', '2008-12-30 12:36:51.000000', NULL, 1),
(5157945, 749620, 3087, '<td valign="top">Kind of strange, I like how the shadows fall into that kind of hump of the white foreground, the background works well, it''s processing really makes it feel timeless, it''s also kind of surreal.</td>', 'Kind of strange, I like how the shadows fall into that kind of hump of the white foreground, the background works well, it''s processing really makes it feel timeless, it''s also kind of surreal.', '2008-12-30 12:37:44.000000', NULL, 1),
(5157946, 749550, 3087, '<td valign="top">Lovely lighting.</td>', 'Lovely lighting.', '2008-12-30 12:37:56.000000', NULL, 1),
(5157947, 749443, 3087, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2008-12-30 12:38:09.000000', NULL, 1),
(5157949, 749244, 3087, '<td valign="top">Lovely light.</td>', 'Lovely light.', '2008-12-30 12:38:54.000000', NULL, 1),
(5157950, 749393, 3087, '<td valign="top">This is fabulous, I love it. The shapes of the walls, that wonderful curving staircase and it''s shadows are great. So too are the textures and details of the dirty wals and the birds. It''s all good.</td>', 'This is fabulous, I love it. The shapes of the walls, that wonderful curving staircase and it''s shadows are great. So too are the textures and details of the dirty wals and the birds. It''s all good.', '2008-12-30 12:40:01.000000', NULL, 1),
(5157952, 748699, 35804, '<td valign="top">...learning to fly...love this.</td>', '...learning to fly...love this.', '2008-12-30 12:40:15.000000', NULL, 1),
(5158022, 748523, 50695, '<td valign="top">lovely and dynamic. getting this shot in basic editing is a real achievement.<br/> <br/>I love the mysterious excitement of the lights in air and water. I''m giving you a Posthumous Blue.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/bluepost.jpg'', strrpos(''//blackyak.com/dpc/bluepost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/bluepost.jpg"/></td>', 'lovely and dynamic. getting this shot in basic editing is a real achievement. I love the mysterious excitement of the lights in air and water. I''m giving you a Posthumous Blue. ', '2008-12-30 14:10:36.000000', NULL, 1),
(5158023, 749651, 50695, '<td valign="top">This is such a beautiful, refined abstract. I might have given you a blue, but I gave that to a shadowier image. Still, this uses shading if not shadow. I give you a Posthumous Red.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/redpost.jpg'', strrpos(''//blackyak.com/dpc/redpost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/redpost.jpg"/></td>', 'This is such a beautiful, refined abstract. I might have given you a blue, but I gave that to a shadowier image. Still, this uses shading if not shadow. I give you a Posthumous Red. ', '2008-12-30 14:11:52.000000', NULL, 1),
(5158027, 749116, 50695, '<td valign="top">Beautiful work. This just shines.</td>', 'Beautiful work. This just shines.', '2008-12-30 14:13:10.000000', NULL, 1),
(5158031, 749393, 50695, '<td valign="top">Gorgeous. A fitting tribute.</td>', 'Gorgeous. A fitting tribute.', '2008-12-30 14:14:18.000000', NULL, 1),
(5158035, 748962, 50695, '<td valign="top">beautiful! The competition was tough, but for the sheer complexity of shadows on curves, I will give this a Posthumous Yellow.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/yellowpost.jpg'', strrpos(''//blackyak.com/dpc/yellowpost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/yellowpost.jpg"/></td>', 'beautiful! The competition was tough, but for the sheer complexity of shadows on curves, I will give this a Posthumous Yellow. ', '2008-12-30 14:15:28.000000', NULL, 1),
(5158086, 749247, 66201, '<td valign="top">Very striking: minimalist impact and GREAT shadow detail. Hope this does well.</td>', 'Very striking: minimalist impact and GREAT shadow detail. Hope this does well.', '2008-12-30 14:58:19.000000', NULL, 1),
(5158214, 748927, 47470, '<td valign="top">My art professor''s favorite thing to photograph was these type of chairs (in black and white) because he said they make the best shadows : )</td>', 'My art professor''s favorite thing to photograph was these type of chairs (in black and white) because he said they make the best shadows : )', '2008-12-30 16:42:20.000000', NULL, 1),
(5158215, 748868, 47470, '<td valign="top">Great shadow in the background, but I wish the lighting was a bit better on his face.</td>', 'Great shadow in the background, but I wish the lighting was a bit better on his face.', '2008-12-30 16:43:13.000000', NULL, 1),
(5158218, 749467, 47470, '<td valign="top">Took me a minute to understand the perspective on this one--nice use of rotation.</td>', 'Took me a minute to understand the perspective on this one--nice use of rotation.', '2008-12-30 16:44:28.000000', NULL, 1),
(5158223, 749282, 47470, '<td valign="top">5?  I thought the answer to life, the universe and everything was 42! : )<br/>Nice shadows though.  I wish the center lifesaver(?)/circle was a bit more straight to the camera.</td>', '5?  I thought the answer to life, the universe and everything was 42! : )Nice shadows though.  I wish the center lifesaver(?)/circle was a bit more straight to the camera.', '2008-12-30 16:48:42.000000', NULL, 1),
(5158226, 749464, 67258, '<td valign="top">I love the cave painting like quality the shadow has.  Works really well.</td>', 'I love the cave painting like quality the shadow has.  Works really well.', '2008-12-30 16:50:54.000000', NULL, 1),
(5158229, 749114, 67258, '<td valign="top">Original idea, and very effective.</td>', 'Original idea, and very effective.', '2008-12-30 16:51:29.000000', NULL, 1),
(5158231, 748380, 3540, '<td valign="top">like this a lot.  I''d frame it differently, but its a nice crisp image. 8</td>', 'like this a lot.  I''d frame it differently, but its a nice crisp image. 8', '2008-12-30 16:52:44.000000', NULL, 1),
(5158233, 749114, 3540, '<td valign="top">I''d take this idea a different way, but I like the idea.  The image is good, but not great 6</td>', 'I''d take this idea a different way, but I like the idea.  The image is good, but not great 6', '2008-12-30 16:53:54.000000', NULL, 1),
(5158234, 749451, 3540, '<td valign="top">Beautiful contrast.  great idea and nicely done -9</td>', 'Beautiful contrast.  great idea and nicely done -9', '2008-12-30 16:54:39.000000', NULL, 1),
(5158237, 748862, 3540, '<td valign="top">Nice detail.  Not sure the shadow falling partly outside of the frame is effective for this challenge. 7</td>', 'Nice detail.  Not sure the shadow falling partly outside of the frame is effective for this challenge. 7', '2008-12-30 16:55:46.000000', NULL, 1),
(5158241, 749398, 3540, '<td valign="top">badly pixelated. aside from that, it has some potential, but just isn''t done with enough attention to the composition of the photo</td>', 'badly pixelated. aside from that, it has some potential, but just isn''t done with enough attention to the composition of the photo', '2008-12-30 16:58:46.000000', NULL, 1),
(5158244, 749492, 3540, '<td valign="top">I don''t find this having a lot of relevance to this challenge.  Sure there are shadows, but if anything they''re detrimental to the subject</td>', 'I don''t find this having a lot of relevance to this challenge.  Sure there are shadows, but if anything they''re detrimental to the subject', '2008-12-30 17:00:03.000000', NULL, 1),
(5158251, 748869, 3540, '<td valign="top">Cute pic.  Texture on the leaf is first class. 8</td>', 'Cute pic.  Texture on the leaf is first class. 8', '2008-12-30 17:05:50.000000', NULL, 1),
(5158256, 749619, 3540, '<td valign="top">Almost really good.  Not sure I like the portrait framing with a crop this tight.  The eye on the left has to be shown, or not shown.  I don''t like that its visible but not totally.  6</td>', 'Almost really good.  Not sure I like the portrait framing with a crop this tight.  The eye on the left has to be shown, or not shown.  I don''t like that its visible but not totally.  6', '2008-12-30 17:08:10.000000', NULL, 1),
(5158259, 748912, 3540, '<td valign="top">The sun seems pretty high... Not sure where you''re at, but it doesn''t look all that early.  This photo looks like you were shooting at this wonderful landscape but this silly tree happened to fall from the sky, right in the way.</td>', 'The sun seems pretty high... Not sure where you''re at, but it doesn''t look all that early.  This photo looks like you were shooting at this wonderful landscape but this silly tree happened to fall from the sky, right in the way.', '2008-12-30 17:10:32.000000', NULL, 1),
(5158262, 749407, 3540, '<td valign="top">"Oversaturated or oversharpened" seems to be a more appropriate title for this.  The composition is nice though</td>', '"Oversaturated or oversharpened" seems to be a more appropriate title for this.  The composition is nice though', '2008-12-30 17:12:06.000000', NULL, 1),
(5158267, 749433, 3540, '<td valign="top">Awesome view.  Not sure this is really relevant to this challenge, but a nice photo anyway. 7</td>', 'Awesome view.  Not sure this is really relevant to this challenge, but a nice photo anyway. 7', '2008-12-30 17:14:05.000000', NULL, 1),
(5158268, 749536, 3540, '<td valign="top">Looks like a painting.  Doesn''t really do it for me though</td>', 'Looks like a painting.  Doesn''t really do it for me though', '2008-12-30 17:16:43.000000', NULL, 1),
(5158272, 748157, 3540, '<td valign="top">A little too much negative space between the subjects.  Other than that, I like the idea a lot. 8</td>', 'A little too much negative space between the subjects.  Other than that, I like the idea a lot. 8', '2008-12-30 17:18:18.000000', NULL, 1),
(5158275, 749594, 3540, '<td valign="top">Not sure how this fits in this challenge, but that is an awesome building and there are even fountains.  Its a solid photo regardless. 6</td>', 'Not sure how this fits in this challenge, but that is an awesome building and there are even fountains.  Its a solid photo regardless. 6', '2008-12-30 17:19:55.000000', NULL, 1),
(5158284, 749281, 3540, '<td valign="top">Figuratively effective.  I''m debating whether or not it would be more effective b&amp;w as you could boost the contrast to make the shadows darker .  I think you could have uncoiled the chain effectively.  Good image though. 7</td>', 'Figuratively effective.  I''m debating whether or not it would be more effective b&w as you could boost the contrast to make the shadows darker .  I think you could have uncoiled the chain effectively.  Good image though. 7', '2008-12-30 17:23:14.000000', NULL, 1),
(5158287, 748535, 3540, '<td valign="top">I really like this one.  I''d be a little more cautious photographing someone else''s art, unless of course this is yours, that go right ahead. 9</td>', 'I really like this one.  I''d be a little more cautious photographing someone else''s art, unless of course this is yours, that go right ahead. 9', '2008-12-30 17:25:15.000000', NULL, 1),
(5158291, 749537, 3540, '<td valign="top">I''d have focused more on the mountains.  The sky doesn''t hold my interest nearly as well.</td>', 'I''d have focused more on the mountains.  The sky doesn''t hold my interest nearly as well.', '2008-12-30 17:26:58.000000', NULL, 1),
(5158294, 748069, 3540, '<td valign="top">This is a wild photo.  lots of colors introduced, a good point of interest and definitely relevant to this challenge.  Great work 10</td>', 'This is a wild photo.  lots of colors introduced, a good point of interest and definitely relevant to this challenge.  Great work 10', '2008-12-30 17:28:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5158299, 749391, 3540, '<td valign="top">Too much water, not enough sky.  I just told someone the opposite thing a few photos ago.  Thy sky is glorious in this photo, I''d feature it more. 6</td>', 'Too much water, not enough sky.  I just told someone the opposite thing a few photos ago.  Thy sky is glorious in this photo, I''d feature it more. 6', '2008-12-30 17:31:08.000000', NULL, 1),
(5158301, 748864, 3540, '<td valign="top">much potential.  Whatever is in the way on the bottom right really hurts the great drama you''ve captured in the rest of the image.  6</td>', 'much potential.  Whatever is in the way on the bottom right really hurts the great drama you''ve captured in the rest of the image.  6', '2008-12-30 17:32:51.000000', NULL, 1),
(5158307, 748679, 3540, '<td valign="top">Honestly, is this the best book you could find to do this?  This is yet another photographic cliche and they can be effective if you do them well.  I''ve seen this picture done 1000 times, never in a travel guide.  I reckon that makes it original.  Not effective, but original.</td>', 'Honestly, is this the best book you could find to do this?  This is yet another photographic cliche and they can be effective if you do them well.  I''ve seen this picture done 1000 times, never in a travel guide.  I reckon that makes it original.  Not effective, but original.', '2008-12-30 17:34:54.000000', NULL, 1),
(5158315, 749335, 3540, '<td valign="top">Not a bad image.  Not relevant to this challenge outside of the title.  Good capture, but not great. 6</td>', 'Not a bad image.  Not relevant to this challenge outside of the title.  Good capture, but not great. 6', '2008-12-30 17:37:37.000000', NULL, 1),
(5158320, 749443, 3540, '<td valign="top">wonderful colors.  Lacking a good focal point, but its still a nice image 8</td>', 'wonderful colors.  Lacking a good focal point, but its still a nice image 8', '2008-12-30 17:38:38.000000', NULL, 1),
(5158323, 749428, 3540, '<td valign="top">Composition is weak.  The photo quality is poor.  I''m not seeing what you''re trying to say with this photo.</td>', 'Composition is weak.  The photo quality is poor.  I''m not seeing what you''re trying to say with this photo.', '2008-12-30 17:40:13.000000', NULL, 1),
(5158325, 748901, 3540, '<td valign="top">Wow! A ring that makes a heart!  How original!  All sarcasm aside, its a decent picture.  Nothing to make it suck, but nothing to make it stand out of the 1000 pictures I''ve seen like this.  Like Simon would say from American Idol... "Its forgettable" 5</td>', 'Wow! A ring that makes a heart!  How original!  All sarcasm aside, its a decent picture.  Nothing to make it suck, but nothing to make it stand out of the 1000 pictures I''ve seen like this.  Like Simon would say from American Idol... "Its forgettable" 5', '2008-12-30 17:42:27.000000', NULL, 1),
(5158326, 749346, 3540, '<td valign="top">Textures are one of my favorite things.  This is really nice. 9</td>', 'Textures are one of my favorite things.  This is really nice. 9', '2008-12-30 17:42:56.000000', NULL, 1),
(5158329, 749356, 3540, '<td valign="top">unusual white and black specks on the glass.  Not sure its that distracting, but its sure not helping.  An okay photo -5</td>', 'unusual white and black specks on the glass.  Not sure its that distracting, but its sure not helping.  An okay photo -5', '2008-12-30 17:45:07.000000', NULL, 1),
(5158331, 749378, 3540, '<td valign="top">Forget the challenge on this one, go for the icy trees shot.  the shadow of the tree is not isolated enough to make it effective.  If you had a single tree on a large flat plane, that''s a different story</td>', 'Forget the challenge on this one, go for the icy trees shot.  the shadow of the tree is not isolated enough to make it effective.  If you had a single tree on a large flat plane, that''s a different story', '2008-12-30 17:47:05.000000', NULL, 1),
(5158333, 749393, 3540, '<td valign="top">I think I would''ve tried framing this one a bit differently.  Maybe a portrait crop with the bottom of the handrail in the corner of the shot.  Great idea, There is a ton of potential with this subject. 7</td>', 'I think I would''ve tried framing this one a bit differently.  Maybe a portrait crop with the bottom of the handrail in the corner of the shot.  Great idea, There is a ton of potential with this subject. 7', '2008-12-30 17:49:00.000000', NULL, 1),
(5158334, 749585, 3540, '<td valign="top">I gave this a 5 originally but I''m changing my mind... I must''ve been sleepy this morning.  8</td>', 'I gave this a 5 originally but I''m changing my mind... I must''ve been sleepy this morning.  8', '2008-12-30 17:50:31.000000', NULL, 1),
(5158409, 749651, 100831, '<td valign="top">I like the photo but I don''t really see shadows</td>', 'I like the photo but I don''t really see shadows', '2008-12-30 18:58:01.000000', NULL, 1),
(5158411, 748971, 100831, '<td valign="top">great story going on here</td>', 'great story going on here', '2008-12-30 18:59:55.000000', NULL, 1),
(5158413, 749585, 100831, '<td valign="top">nice</td>', 'nice', '2008-12-30 19:00:12.000000', NULL, 1),
