(5158420, 749590, 100831, '<td valign="top">interesting geometry</td>', 'interesting geometry', '2008-12-30 19:02:58.000000', NULL, 1),
(5158459, 749451, 83785, '<td valign="top">Nice photo, interesting execution of idea</td>', 'Nice photo, interesting execution of idea', '2008-12-30 19:28:02.000000', NULL, 1),
