INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5174062, 749590, 60862, '<td valign="top">Congrats on the ribbon, Robert!  Every time I see an interesting pattern on a building, I think of you.</td>', 'Congrats on the ribbon, Robert!  Every time I see an interesting pattern on a building, I think of you.', '2009-01-06 00:29:38.000000', NULL, 0),
(5174079, 749036, 54645, '<td valign="top">Critique Club<br/> <br/>Initial impression...very pleasing photograph, and I like the texture of the snow. This was represented well. The composition good be stronger with a more interesting placement of the main subjects which are the covered logs. Possibly on a diagonal or from a different perspective. Greater depth of field can be gained by placing the focus further back in the scene. Details in the background would have added to the interest of the photograph. You did a nice job of exposing the snow, but overall it could be brighter. Finally, as mentioned in the comments, the lack of prominent shadows hurt your score based on the challenge topic. <br/> <br/>Keep shooting and entering challenges...<br/> <br/>Cheers!<br/> <br/>Ben</td>', 'Critique Club Initial impression...very pleasing photograph, and I like the texture of the snow. This was represented well. The composition good be stronger with a more interesting placement of the main subjects which are the covered logs. Possibly on a diagonal or from a different perspective. Greater depth of field can be gained by placing the focus further back in the scene. Details in the background would have added to the interest of the photograph. You did a nice job of exposing the snow, but overall it could be brighter. Finally, as mentioned in the comments, the lack of prominent shadows hurt your score based on the challenge topic.  Keep shooting and entering challenges... Cheers! Ben', '2009-01-06 00:39:53.000000', NULL, 0),
(5174374, 748830, 61961, '<td valign="top">Sorry to hear about the disqualification, Chris.</td>', 'Sorry to hear about the disqualification, Chris.', '2009-01-06 08:41:05.000000', NULL, 0),
(5174576, 748830, 30791, '<td valign="top">wow that is a load of bull</td>', 'wow that is a load of bull', '2009-01-06 10:53:18.000000', NULL, 0),
(5174594, 749378, 68947, '<td valign="top">CONGRATULATIONS JO!!!!!!!  WAY TO GO!!!<br/> <br/>This is an absolutely stunning image.  It has such a feel to it and "mood".  LOVE IT!!!<br/> <br/>ETA:  I love the shadow from the tree.  I think it works perfectly well to add "mood" to this shot.  Getting rid of the shadow would have focused solely on the tree itself and lent itself to more of a stock shot look.  This entire shot, including the shadow has a real feel to it and it''s what makes the shot what it is!  <br/> <br/>Photographers do not live by stock shots alone! ;-)<br/><br/><i>Message edited by author 2009-01-06 11:11:30.</i></td>', 'CONGRATULATIONS JO!!!!!!!  WAY TO GO!!! This is an absolutely stunning image.  It has such a feel to it and "mood".  LOVE IT!!! ETA:  I love the shadow from the tree.  I think it works perfectly well to add "mood" to this shot.  Getting rid of the shadow would have focused solely on the tree itself and lent itself to more of a stock shot look.  This entire shot, including the shadow has a real feel to it and it''s what makes the shot what it is!   Photographers do not live by stock shots alone! ;-)', '2009-01-06 11:07:52.000000', '2009-01-06 11:11:30.000000', 0),
(5174599, 749378, 80096, '<td valign="top">Wow! What a surprise! A ribbon afterall, this is a very happy day for me! Thanks to everyone for all your wonderful comments.</td>', 'Wow! What a surprise! A ribbon afterall, this is a very happy day for me! Thanks to everyone for all your wonderful comments.', '2009-01-06 11:13:20.000000', NULL, 0),
(5176321, 749467, 53814, '<td valign="top">of course... another great one Jan...</td>', 'of course... another great one Jan...', '2009-01-06 23:55:27.000000', NULL, 0),
(5176735, 749396, 48560, '<td valign="top">the amount of detail on the grass keeps my eyes busy. lovely!</td>', 'the amount of detail on the grass keeps my eyes busy. lovely!', '2009-01-07 02:06:55.000000', NULL, 0),
(5178784, 748830, 89341, '<td valign="top">&gt; I duplicated the background, used a Gaussian Blur on it and reduced opacity to 51%. If I can use Gaussian Blur, do I have to use it on the background layer?<br/> <br/>Yes, that is the issue. You can''t duplicate the background layer in basic, you can only use layers with no image data, eg a curves or levels layer and only applied in normal mode. So you can only use Gaussian Blur on the background layer in basic (and therefore no option to change opacity). Hope that makes sense, if not pm me ....<br/> <br/>Fine to duplicate background layers in advanced and do what you did or apply layers in duplicate or soft light mode etc.<br/> <br/>It''s still a great image and a shame about the DQ</td>', '> I duplicated the background, used a Gaussian Blur on it and reduced opacity to 51%. If I can use Gaussian Blur, do I have to use it on the background layer? Yes, that is the issue. You can''t duplicate the background layer in basic, you can only use layers with no image data, eg a curves or levels layer and only applied in normal mode. So you can only use Gaussian Blur on the background layer in basic (and therefore no option to change opacity). Hope that makes sense, if not pm me .... Fine to duplicate background layers in advanced and do what you did or apply layers in duplicate or soft light mode etc. It''s still a great image and a shame about the DQ', '2009-01-07 19:52:59.000000', NULL, 0),
(5189137, 748521, 94876, '<td valign="top">I like this image a lot.</td>', 'I like this image a lot.', '2009-01-13 12:51:42.000000', NULL, 0),
(5209607, 748523, 67697, '<td valign="top">Several times I have been meaning to comment on this and have failed.  So here we go...  I love this black and white conversion.  It reminds me of something you might see in a jazz bar - it just has that kind of mood.  I like the lights on the bridge.  They fascinate me for some reason.  No clue why lol.  Good photo.</td>', 'Several times I have been meaning to comment on this and have failed.  So here we go...  I love this black and white conversion.  It reminds me of something you might see in a jazz bar - it just has that kind of mood.  I like the lights on the bridge.  They fascinate me for some reason.  No clue why lol.  Good photo.', '2009-01-21 13:33:26.000000', NULL, 0),
